const lastSyncedAt = new Date().toISOString();
const items = $input.all().map((item) => item.json).filter((item) => item?.Id);

function categoryPath(item) {
  const fullName = item.FullyQualifiedName ? String(item.FullyQualifiedName) : '';
  if (fullName.includes(':')) {
    return fullName.split(':').slice(0, -1).join(' > ') || null;
  }
  return item.ParentRef?.name ?? null;
}

const rows = items.map((item) => ({
  qbo_product_id: String(item.Id),
  qbo_product_name: item.Name ? String(item.Name) : String(item.Id),
  qbo_category_path: categoryPath(item),
  active: item.Active ?? null,
  raw: item,
  source: 'qbo_api_sync',
  last_synced_at: lastSyncedAt,
  updated_at: lastSyncedAt,
}));

const categories = rows.reduce((acc, row) => {
  const key = row.qbo_category_path ?? '(uncategorized)';
  acc[key] = (acc[key] ?? 0) + 1;
  return acc;
}, {});

return [{
  json: {
    fetchedCount: items.length,
    rows,
    categories,
    sample: rows.slice(0, 10).map((row) => ({
      qbo_product_id: row.qbo_product_id,
      qbo_product_name: row.qbo_product_name,
      qbo_category_path: row.qbo_category_path,
      active: row.active,
    })),
    endpointNote: 'QBO Item getAll with WHERE Active IN (true, false) is intended to fetch active and inactive product/service records. If QBO rejects this filter, keep docs/data-references/qbo-product-services.csv as fallback and inspect endpoint support.',
  },
}];

const mapped = $('Map QBO Item Rows').first().json;
const upsertedRows = $input.all().map((item) => item.json);

return [{
  json: {
    status: 'ok',
    fetchedCount: mapped.fetchedCount,
    upsertedCount: upsertedRows.length,
    categories: mapped.categories,
    sample: upsertedRows.slice(0, 10).map((row) => ({
      qbo_product_id: row.qbo_product_id,
      qbo_product_name: row.qbo_product_name,
      qbo_category_path: row.qbo_category_path,
      active: row.active,
    })),
    endpointNote: mapped.endpointNote,
  },
}];
